import { Check } from "lucide-react";
import type { ReactNode } from "react";
import { voiceSourceForEngine, type VoiceSource } from "@readaloud/tokens";
import { cn } from "../lib/cn";
import type { Voice } from "../lib/types";
import { VoiceTile } from "./VoiceTile";

export interface VoiceCardProps {
  voice: Voice;
  selected?: boolean;
  previewing?: boolean;
  /** The preview is still being generated by the speech server: nothing can be heard yet. */
  generating?: boolean;
  /** Service that renders the voice; worked out from its engine when left out. */
  source?: VoiceSource;
  onPreview: () => void;
  onSelect: () => void;
  /** Icon buttons for managing the voice, e.g. send a gallery voice back to Studio, re-record or delete a clone. */
  actions?: VoiceCardAction[];
  /** Short status under the tags, e.g. how much of a document this voice has prepared. */
  note?: string;
  className?: string;
}

export interface VoiceCardAction {
  /** Accessible name and tooltip, e.g. "Delete My narrator". */
  label: string;
  icon: ReactNode;
  onClick: () => void;
  danger?: boolean;
}

/** A selectable voice: tap the portrait to hear it, "Use" to read with it. */
export function VoiceCard({ voice, selected, previewing, generating, source = voice.engine ? voiceSourceForEngine(voice.engine) : undefined, onPreview, onSelect, actions, note, className }: VoiceCardProps) {
  const waiting = !!previewing && !!generating;
  return (
    <VoiceTile
      voice={voice}
      source={source}
      selected={selected}
      data-voice={voice.id}
      className={className}
      preview={{
        label: waiting ? `Generating preview of ${voice.name}` : previewing ? `Playing preview of ${voice.name}` : `Preview ${voice.name}`,
        state: waiting ? "generating" : previewing ? "playing" : "idle",
        onClick: onPreview,
      }}
      corner={actions?.map((action) => (
        <button
          key={action.label}
          type="button"
          onClick={action.onClick}
          aria-label={action.label}
          title={action.label}
          className={cn("grid size-8 place-items-center rounded-control border-0 bg-transparent text-fg2 hover:bg-bg3", action.danger ? "hover:text-danger" : "hover:text-fg")}
        >
          {action.icon}
        </button>
      ))}
    >
      <div className="flex max-w-full flex-col gap-0.5 text-[12px] text-fg2">
        {/* The sample's progress takes the language's place, so the tile keeps its height. */}
        <div className={cn("font-mono", previewing && "text-fg")}>{waiting ? "Generating…" : previewing ? "Playing…" : voice.lang}</div>
        {voice.tags.length > 0 && <div className="[overflow-wrap:anywhere]">{voice.tags.join(" · ")}</div>}
        {note && <div>{note}</div>}
      </div>
      <button
        type="button"
        onClick={onSelect}
        aria-pressed={!!selected}
        className={cn(
          "mt-auto inline-flex h-[34px] w-full select-none items-center justify-center gap-1.5 rounded-pill border text-[13px] font-semibold text-fg",
          selected ? "cursor-default border-transparent bg-transparent" : "border-line bg-bg2 hover:bg-bg3",
        )}
      >
        {selected && <Check size={14} strokeWidth={2} aria-hidden />}
        {selected ? "Selected" : "Use"}
      </button>
    </VoiceTile>
  );
}
